// stringUtils.js
export const WERSJA = "1.0.0";
export function capitalize(str) { return str.charAt(0).toUpperCase() + str.slice(1); }
export default function odwroc(str) { return [...str].reverse().join(""); }

// inny-plik.js
import * as StrUtils from "./stringUtils.js";
console.log(StrUtils.WERSJA);             // "1.0.0"
console.log(StrUtils.capitalize("test")); // "Test"
console.log(StrUtils.default("test"));    // "tset" - eksport domyslny pod kluczem 'default'

// mathUtils.js
export const PI = 3.14159;
export default function pomnoz(a, b) { return a * b; }

// inny-plik.js
import * as MathAll from "./mathUtils.js";
console.log(MathAll.PI);          // 3.14159
console.log(MathAll.default(5, 5)); // 25

// mathUtils.js
export function dodaj(a, b) { return a + b; }
export function odejmij(a, b) { return a - b; }

// inny-plik.js
import * as MatObiekt from "./mathUtils.js";
console.log(MatObiekt.dodaj(10, 20));   // 30
console.log(MatObiekt.odejmij(10, 20)); // -10

// import * as MathUtils from './mathUtils.js' tworzy OBIEKT MathUtils,
// niezaleznie od tego, CZYM byl eksport domyslny w pliku zrodlowym
// (funkcja, klasa, zmienna). Sam obiekt MathUtils nigdy nie jest
// funkcja - jest 'kontenerem' zawierajacym WSZYSTKIE eksporty pliku
// jako swoje pola.
//
// import * as MathUtils from "./mathUtils.js";
// MathUtils(3, 3); // TypeError: MathUtils is not a function
// MathUtils.default(3, 3); // POPRAWNIE - eksport domyslny jest polem 'default'

// Kolory.js
export const CZERWONY = "#f00";
export const ZIELONY = "#0f0";
export const NIEBIESKI = "#00f";

// inny-plik.js
import * as KolorySet from "./Kolory.js";
console.log(KolorySet.CZERWONY);  // "#f00"
console.log(KolorySet.ZIELONY);   // "#0f0"
console.log(KolorySet.NIEBIESKI); // "#00f"

// Namespace import jest uzywany rzadziej, poniewaz:
// 1. Import nazwany/domyslny z konkretnie wypisanymi nazwami jest
//    CZYTELNIEJSZY - od razu widac, jakie DOKLADNIE elementy z modulu
//    sa uzywane w danym pliku, bez potrzeby przeszukiwania calego kodu.
// 2. Narzedzia 'budujace' aplikacje (np. bundlery jak Vite/Webpack)
//    moga lepiej zoptymalizowac koncowy rozmiar aplikacji przez
//    'tree-shaking' (usuwanie nieuzywanego kodu), gdy widza DOKLADNIE,
//    ktore konkretne eksporty sa importowane - namespace import utrudnia
//    te analize, bo teoretycznie MOZE byc uzyty KAZDY eksport modulu.

